import{_ as t,a as r}from"./chunks/66c22362084b0b3b5a14.hSo_Xpn-.js";import{_ as o,C as i,o as n,c as l,j as e,a as h,E as s,a5 as d}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"我的初创公司是如何在6个月内赚到759,900美元的（还没公开发布）","description":"","frontmatter":{"title":"我的初创公司是如何在6个月内赚到759,900美元的（还没公开发布）","originalTitle":"How My Startup Made $759,900 In 6 Months (Without Launching)","date":"2024-04-20","originalUrl":"https://thedankoe.com/letters/how-my-startup-made-759900-in-6-months-without-launching/","minutes":10,"sourceHash":"2be134bdc703eb005433be8d8e31df873635aee4140dc9da5e69502e9b5ecdbe","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-my-startup-made-759900-in-6-months-without-launching/"}]]},"headers":[],"relativePath":"letters/how-my-startup-made-759900-in-6-months-without-launching.md","filePath":"letters/how-my-startup-made-759900-in-6-months-without-launching.md"}'),c={name:"letters/how-my-startup-made-759900-in-6-months-without-launching.md"};function m(u,p,f,_,g,b){const a=i("ArticleMeta");return n(),l("div",null,[p[0]||(p[0]=e("h1",{id:"我的初创公司是如何在6个月内赚到759-900美元的-还没公开发布",tabindex:"-1"},[h("我的初创公司是如何在6个月内赚到759,900美元的（还没公开发布） "),e("a",{class:"header-anchor",href:"#我的初创公司是如何在6个月内赚到759-900美元的-还没公开发布","aria-label":'Permalink to "我的初创公司是如何在6个月内赚到759,900美元的（还没公开发布）"'},"​")],-1)),s(a),p[1]||(p[1]=d('<p>上个周末，我去加拿大多伦多（Toronto）拜访了我的开发团队。</p><p>在<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>，我们的做法有点与众不同，而我想对你敞开心扉。</p><p>我想公开记录我们建立初创公司的过程，这样你就能从我们的成败中学习（相信我，我们已经经历了很多失败）。</p><p>我想谈谈我们是如何在未向公众发布产品的情况下，在6个月内创收759,900美元的。</p><p>问题在于，大多数人都梦想着建立一家大公司，但他们中大多数人的做法都是错的。</p><ul><li>他们认为自己需要启动资金。</li><li>他们认为自己需要投资者和风投资金（VC money）。</li><li>他们认为自己需要将大量资金投入到营销中。</li><li>他们在开发产品时，压根没考虑过如何获取用户，也没想过这个主意到底好不好。</li></ul><p>我们采取了完全不同的方法。</p><p>这种方法的好处是，任何人都可以做到。</p><p>这种方法的坏处是，它需要时间。</p><p>当我降落在多伦多时，我想问问我们的核心开发人员在开发Kortex的过程中学到的最大教训是什么。</p><p>我完全没想到他们会给出那样的答案。</p><p>我觉得你会从他们的话中受益匪浅。</p><p>我们先从这里开始，然后，我会告诉你如何想出一个能盈利的初创公司点子，并在没有外部帮助的情况下为其提供资金。</p><h2 id="不完美、高能动性-high-agency-的人-以及从零开始" tabindex="-1">不完美、高能动性（High-Agency）的人，以及从零开始 <a class="header-anchor" href="#不完美、高能动性-high-agency-的人-以及从零开始" aria-label="Permalink to &quot;不完美、高能动性（High-Agency）的人，以及从零开始&quot;">​</a></h2><p>我先来说说我学到的最大教训。</p><p>我之前没意识到软件开发能有多复杂、多昂贵。</p><p>这不就是一个记笔记的应用程序吗，对吧？</p><p>错了。我们对很多正在使用的软件都觉得理所当然。而且，我们并不打算走廉价的无代码路线，把一个垃圾产品交给你。</p><p>我们的烧钱速度接近每周30,000美元。</p><p>我们已经删除了3到4个主要功能，这些功能耗费了开发人员几个月的时间和精力。</p><p>我们也添加了计划外的主要功能。</p><p>我们已经在进行该应用程序的V2版本设计。</p><p>构建这个应用程序就是一连串不断出现的问题，但我不会选择其他任何方式。</p><p>我们根本不知道自己在做什么，因为你不可能猜到接下来会冒出什么问题。</p><p><strong>所以，我最大的教训是：</strong></p><p>接受不完美地做事。</p><p>是的，我们的成本本可以更低（如果不招募顶尖人才的话）。是的，我们本可以发布一个让我们觉得丢脸的MVP（最小可行性产品）。是的，我们本可以做很多事情，但天呐，我们正在获得宝贵的人生经验，这些经验在未来会带来十倍的回报。</p><p>我们的心态可能会改变，但我们现在的目标不是被收购。我们想在这个世界上打造出一款我们自己想看到的应用程序。一款每天都能改善人们生活的应用程序，就像它已经改善了我的生活一样（说真的，我都对它上瘾了）。</p><p><strong>教训2) 成为一个高能动性个体的重要性</strong></p><p><a href="https://player.vimeo.com/video/936299568?h=3bd8384e1a&amp;dnt=1&amp;app_id=122963" target="_blank" rel="noreferrer">观看原文视频</a></p><p><strong>教训3) 学会作为一匹独狼与团队合作</strong></p><p><a href="https://player.vimeo.com/video/936299497?h=53dd4c4ba4&amp;dnt=1&amp;app_id=122963" target="_blank" rel="noreferrer">观看原文视频</a></p><p><strong>教训4) 从零开始建设比在一家成熟公司工作要耗费更多精力</strong></p><p><a href="https://player.vimeo.com/video/936299451?h=9067a40768&amp;dnt=1&amp;app_id=122963" target="_blank" rel="noreferrer">观看原文视频</a></p><h2 id="建立受众群体的重要性" tabindex="-1">建立受众群体的重要性 <a class="header-anchor" href="#建立受众群体的重要性" aria-label="Permalink to &quot;建立受众群体的重要性&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>大多数人在创业时，甚至连想都没想过社交媒体。</p><p>他们没有意识到它是通往成功的最大“捷径”。</p><p>我们不是在21世纪头十年做生意。科技已经进步了。你不需要花费大量令人筋疲力尽的时间去搞直销、冷启动开发（cold outreach）以及手动寻找潜在客户。</p><p>社交媒体可以让你：</p><ul><li>用内容来测试想法，随后转化为营销，并做成大卖的产品（无需花费一分钱）。</li><li>建立一群在你发布产品时想要购买的受众（因为大多数初创公司都无法获得用户）。</li><li>出售边际成本极低的数字产品以获得成果，并在开发初创项目之前验证你的想法。</li><li>如果你想走那条路，你可以招募开发者、组建团队以及吸引投资者。</li></ul><p>很多人以为我写内容只是为了写内容。</p><p>这部分是事实，但我已经写了40,000条推文，在其他平台上发布了3000多条内容，发送了数百份时事通讯，还发布了数百个YouTube视频。</p><p>正因为如此，我掌握了<em>数据</em>。</p><p>我非常清楚哪些想法能吸引粉丝、抓住注意力、引发争议、带来客户以及获得互动。</p><p>我有一个想法数据库，可以用作产品、融入我的产品、放在销售页面以及用于我的促销活动中。我不需要做任何人工的市场调查，也不需要把时间花在开发产品上去测试它是否好卖。</p><p>通过在社交媒体上写作和建立受众群体，我得以跳过大多数初创企业和公司所经历的苦逼煎熬。</p><p>以下是几个简单的入门步骤：</p><h3 id="_1-创建你的话题树-topic-tree" tabindex="-1">1) 创建你的话题树（Topic Tree） <a class="header-anchor" href="#_1-创建你的话题树-topic-tree" aria-label="Permalink to &quot;1) 创建你的话题树（Topic Tree）&quot;">​</a></h3><p>列出你所有想谈论的兴趣、技能和想法。</p><p>别担心要有多具体，你该操心的是能不能让人产生共鸣。</p><p>别太早深耕于极其狭窄的细分领域。从广泛且适用于大多数人的话题开始。</p><p>适用话题的例子就是你经常在网上看到的那些：生产力、自我提升、健康与健身、社交动态、技能获取、职业建议、商业等等。</p><p>如果你的话题是“面向团队和高管的领导力”，那就把它转化为“自我提升”，或者用一种能让更多人受益的方式来构建它（同时不要剥离吸引你想要的目标受众的潜力）。</p><p>你没必要非得点名团队和高管才能让他们对内容产生共鸣。为他们写作，但要用一种其他人也能从中受益的方式。</p><p>记住，这是社交媒体。它不是定向的。它是随机的。你必须从泛泛而谈开始，然后把人们引导到你的专业领域中去。</p><p>如果你只有100个粉丝，而且你的话题都是细分领域，那你祝自己好运能让足够多的人看到你的内容吧。</p><p>你需要一个更大的受众群体来传播你的名字，从而<em>触达</em>你想要的特定人群。即便你的受众并不全都是潜在买家也没关系。</p><p>我宁愿拥有10万个能把我的名字传播给他们人脉圈中特定人群的人，也不想要1,000个完全了解我在做什么的人。尤其是在我建立一家需要所有我能得到的杠杆、资源和人脉的初创公司时。</p><p>顺便说一句，如果你想获得Kortex的首批访问权限，我们正在举办一个仅限500人的写作训练营（BootCamp）。</p><p>在我们教你如何在社交媒体上写作，以为你的业务、工作或职业生涯建立受众群体时，你将获得1年的Kortex访问权限。</p><p>第一期训练营将于5月13日开始。<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">点击此处查看。</a></p><h3 id="_2-制造声量并关注信号" tabindex="-1">2) 制造声量并关注信号 <a class="header-anchor" href="#_2-制造声量并关注信号" aria-label="Permalink to &quot;2) 制造声量并关注信号&quot;">​</a></h3><p>现在，开始写吧。</p><p>谈论你的兴趣。</p><p>谈论你的观点。</p><p>谈论你的专长。</p><p>谈论你的信仰。</p><p>教给人们你所拥有的技能、在你的领域取得成功所需的心态，以及按照你的教导去做的益处。</p><p>你写的越多，你拥有的数据点就越多。</p><p>模仿那些行之有效的内容。</p><p>建立一个素材库（swipe file），收集那些你希望自己能写出来的绝佳想法。</p><p>研究那些表现优秀的帖子和连带推文（threads）的结构。</p><p>在你写作时，毫不夸张地说，就在旁边打开10到20个你最喜欢的帖子。</p><p>不要盲目地写下你的想法。你的写作需要具备可读性和影响力，并且要使用该平台习惯的风格。</p><p>所有的创作者用相似的方式谈论相似的话题是有原因的……因为这招有效。这种情况偶尔会改变，你需要顺应市场的需求。</p><p>从那里开始，坚持3到6个月。</p><p>回顾你所有的帖子，看看哪些表现更好。</p><p>让这些想法成为你品牌固化的一部分。更频繁地写它们，因为它们会继续表现良好。将它们纳入你的营销、促销以及作为产品的构思中。人们渴望看到更多那样的内容。</p><p>当你通过内容拥有了足够多经过验证的想法时，你就可以进行下一步了。</p><h2 id="如何为你的初创企业融资" tabindex="-1">如何为你的初创企业融资 <a class="header-anchor" href="#如何为你的初创企业融资" aria-label="Permalink to &quot;如何为你的初创企业融资&quot;">​</a></h2><p><img src="'+r+'" alt="You have everything you need to build what you want. It&#39;s 2024. If you have an internet connection, you can be free."></p><p>最后，为了回答你的问题：我们是如何在尚未发布应用程序的情况下，在6个月内赚到近80万美元的？</p><p>答案相对简单，这也是我在几乎每一封商业时事通讯中都谈到过的事情。</p><p>我们有一支由9名开发人员组成的团队在构建Kortex应用程序，以及6名创作者（包括我自己）在建设Kortex大学（Kortex University）——也就是我们教授写作的一方。</p><p>我们对Kortex的首要任务是产生<em>现金流</em>，这样我们就不必引入投资者或继续掏自己的腰包（我投入了自己50万美元作为初期保障来推动开发）。</p><p>我们用之前验证过的想法打造了一款数字产品。</p><p>我们开始建设Kortex的社交媒体和电子邮件列表。我们的X和Instagram账号各自都快有10,000名粉丝了。我们的电子邮件列表也接近10,000名订阅者。</p><p>数字产品的开发和分发成本极低。我已经在自己的品牌下开发了多款数字产品，所以我知道如何快速搞定它。</p><p>简而言之，我们建立了一个教授写作的项目，并用社交媒体流量为其提供动力。</p><p>但是，我不建议一开始就在你的初创企业下做这件事。我建议在你的个人品牌下做这件事，然后，在建立现金流并具备建立初创企业的技能之后，你可以在初创企业的品牌下重复相同的过程。</p><p>以下是要采取的步骤：</p><h3 id="_1-写内容、建项目并开展客户工作" tabindex="-1">1) 写内容、建项目并开展客户工作 <a class="header-anchor" href="#_1-写内容、建项目并开展客户工作" aria-label="Permalink to &quot;1) 写内容、建项目并开展客户工作&quot;">​</a></h3><p>你需要现金流。</p><p>当你开始建立个人品牌并用内容测试想法时（如上所述），你就会开始感觉到自己能在哪些方面帮助别人。</p><p>将你的专长变成一个项目，帮助人们做到你所做成的事。</p><p>作为一个作家，我帮助人们写作。</p><p>作为一名健康狂人，你可以帮助人们健身。</p><p>作为一名生产力专家，你可以帮助人们变得更有生产力。</p><p>是的，在你能通过生意去帮助别人之前，你确实需要先在某件事情上变得出色。</p><p>你的工作是建立一套课程体系，并通过每周的通话、工作表和任务进行一对一指导，从而让人们取得成果。</p><p>当你没有大量受众时，销售产品还没有意义。你需要向每个客户收取1000至5000美元以上的费用。</p><p>我很快会在未来的信件中讨论这个过程。</p><h3 id="_2-取得成果、扩大受众并将你的服务-offer-产品化" tabindex="-1">2) 取得成果、扩大受众并将你的服务（Offer）产品化 <a class="header-anchor" href="#_2-取得成果、扩大受众并将你的服务-offer-产品化" aria-label="Permalink to &quot;2) 取得成果、扩大受众并将你的服务（Offer）产品化&quot;">​</a></h3><p>随着你的受众增长，你就有了更多的杠杆。</p><p>我们在<a href="/letters/zero-to-1-million-as-a-one-person-business-while-working-2-4-hours-per-day">《作为一人企业从零赚到100万美元》</a>中讨论过这个渐进过程。</p><p>在这些步骤之间，你的全职工作就是改进你的项目，为你的客户带来更好的结果。</p><p>与他们密切合作并研究他们的问题。</p><p>结果才是一切。你的成果将为你带来更多的客户以及一个能盈利的初创点子。</p><p>而且，既然你已经围绕这点建立了一批受众，你就不必太担心如何获得初始用户了。你的来访者、客户和读者，足以验证那个源于建立你个人品牌的初创想法。</p><p>你的受众里拥有更多的流量和潜在客户，因此，将你项目的一部分转化成一门能让更多人接触到的课程，才是明智之举。</p><p>你可以通过两种方式做到这一点：</p><ol><li><strong>同期群课程</strong> – 你有课程大纲、社群和直播连线，来引导一群人完成这个项目。你可以为这种结构收取更高的费用，并每 1-3 个月推出一期。</li><li><strong>常规课程</strong> – 在这里，你只是把课程大纲当作一门课来卖。好处是它需要你做的工作极少。坏处是你只能发布一次，且收费较低。</li></ol><p>在我的品牌下，我对产品进行了多次迭代，最终达到了 2 Hour Writer 成为我最畅销课程的程度。</p><p>我拥有一批我曾帮助过的写作者和创作者受众。</p><p>光是 2 Hour Writer 这一门课就有将近 15,000 名学生，利用我的系统开发一款写作应用，来帮助他们优化写作流程，显然是合情合理的。</p><h3 id="_3-建立你的初创公司并重复这个过程" tabindex="-1">3) 建立你的初创公司并重复这个过程 <a class="header-anchor" href="#_3-建立你的初创公司并重复这个过程" aria-label="Permalink to &quot;3) 建立你的初创公司并重复这个过程&quot;">​</a></h3><p>现在，你拥有了：</p><ul><li>数以千计的社交媒体帖子，你可以从中提取关于哪些方法有效的数据。</li><li>几十个你亲自指导过的客户，通过你的帮助，他们能在你所从事的领域做得更好。</li><li>成百上千名能够从你的初创想法中受益的学生。</li><li>一个利润极高的数字产品业务，拥有足够的现金流，让你能开始为你的初创公司打造产品和团队。</li></ul><p>你解决了大多数初创公司面临的问题：</p><p>他们能做出一个还凑合的产品，但却无法获得用户。因此他们赚不到钱。而且，他们没有一个属于自己的、能够产生现金流的业务，既无法借此验证他们的初创想法，也不能为初创公司的增长提供燃料。</p><p>在这个阶段，为你的初创公司重复上述过程。</p><p>建立社交媒体账号。</p><p>开始用与你初创公司相关的内容来测试想法。</p><p>从客户服务开始，构建你的价值阶梯。</p><p>为这些最初的客户拿到结果，并进一步将其产品化为一门同期群或常规课程。</p><p>雇佣一个团队来负责品牌的开发和教育板块，这样你就能做得比以前更快。</p><p>做了所有这些，我们仍然可能会失败。Kortex 完全可能最终毫无建树，而我们对此能够坦然接受。所有这些建议都取决于你的技能，而不是运气。</p><p>我希望这在为你构建初创公司提供宏观路线图方面有所帮助。</p><p>在 Kortex 的构建过程中，我会分享更多关于我们是如何打造它的内容。</p><p>感谢你的阅读，祝你享受余下的周末时光。</p><p>Dan</p><hr><p><a href="/en/letters/how-my-startup-made-759900-in-6-months-without-launching">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',134))])}const w=o(c,[["render",m]]);export{y as __pageData,w as default};
